INSERT INTO facts VALUES(15,'Docker image kubric-gpu built: Blender 3.6.15 LTS + CUDA 12.2 + RTX 4060 support. Key fix: pip OpenEXR conflicts with Blender''s built-in OpenEXR 3.0 (ABI mismatch → segfault). Solution: use Blender''s bundled OpenImageIO to read multilayer EXR files. Patched kubric/renderer/blender_utils.py with _get_render_layers_from_exr_bpy() using channel name mapping. Dockerfile at Dockerfile.kubric-gpu, entrypoint at entrypoint.sh. Do NOT install OpenEXR pip package.','general','',0.5,0,0,'2026-05-22 13:06:07','2026-05-22 13:06:07',NULL);
