INSERT INTO facts VALUES(40,'**最高优先级编码准则**：1）先想后写——不假设、不隐藏困惑、呈现权衡；2）简单优先——最小代码解决问题，不写投机性功能；3）手术式修改——只动必须的，不顺手改无关代码，每行改动必须追溯到用户需求；4）目标驱动——定义成功标准并循环验证，多步任务先列计划。效果标准：diff 中无多余改动、不过度设计、问题在动手前澄清。此准则适用于所有 AI 工具（Hermes、Claude Code、Codex、OpenCode），永远最先考虑。','user_pref','coding, guidelines, priority, all-tools',0.900000000000000022,0,0,'2026-05-25 07:20:01','2026-05-25 07:21:51',NULL);
